// Código-fonte original do site de exemplo: é isto que quem copia quer ler.
const RECEITA = "receita-da-casa";
function listar(): void {
  const lista = document.getElementById("lista");
  if (!lista) return;
  for (const nome of ["Caneca", "Camiseta", "Adesivo"]) {
    const item = document.createElement("li");
    item.textContent = nome;
    lista.appendChild(item);
  }
}
document.documentElement.setAttribute("data-receita", RECEITA.length > 0 ? "ok" : "");
listar();
